import type { EvalBucket, DifficultyLevel } from "@prisma/client";

/**
 * The v4.5 prompt bank (2026-10-08): 108 questions aimed at where speakers
 * still judge the model's Igala illegible, and at the rules Salem Ejeba and
 * Lydia Wiernik asked for. The data lives here, apart from the seed script
 * (prisma/seed-prompt-bank-v45.ts), so the bank's invariants are tested
 * without a database (prompt-bank-v45.test.ts). Why each family exists, with
 * the evidence promptIds, is on every row and in
 * tasks/prompt-bank-v45-evidence-2026-10-08.md.
 */

export const V45_PROVENANCE = "claude_authored_v45_2026_10_08";

export interface BankPrompt {
  promptId: string;
  bucket: EvalBucket;
  text: string;
  difficultyLevel: DifficultyLevel;
  expectedCulturalContext: string | null;
  /** Which family this prompt belongs to (see the header). */
  family: string;
  /** The measured failure it probes, with the evidence promptIds. Not shown to annotators. */
  rationale: string;
  /** The rule the speaker's answer should teach us. Not shown to annotators. */
  targetRule: string;
  /** Where every Igala token in the text comes from; "none" when the prompt has no Igala. */
  igalaSources: string[];
}

