export const STOP = new Set(
  "a an the and or of to in on at for with from by as is are was were be been it its this that these those you your yours he she they them his her their we our i me my into onto out up down over under about than then so if not no do does did would could should can will may might one two three say said tell write give put how what which who whom when where why".split(
    " ",
  ),
);
export function contentWords(text: string): Set<string> {
  return new Set(
    text
      .toLowerCase()
      .replace(/[^\p{L}\p{M}\p{N}' ]+/gu, " ")
      .split(/\s+/)
      .filter((w) => w.length > 2 && !STOP.has(w)),
  );
}
export function jaccard(a: Set<string>, b: Set<string>): number {
  let inter = 0;
  for (const w of a) if (b.has(w)) inter++;
  const union = a.size + b.size - inter;
  return union === 0 ? 0 : inter / union;
}
